// Prototype de conception v0.5. Toutes les identités, salles et mesures sont locales/fictives.
// Aucun mot de passe n'est conservé; aucun OAuth, stockage de résultats ou serveur de jeu.
const app = document.getElementById('page-content');
const dialog = document.getElementById('site-dialog');
const state = { locale:'fr', theme:'light', brand:'Typulso', identity:'anonymous', pseudo:'Nova', page:'home', scenario:'normal', ready:false, host:false, focus:false, pending:'lobby', practice:false, sound:false, motion:true, effects:true, typing:'', typingKey:'', room:{name:'Le sprint des mots',access:'semi',language:'fr',content:'text',duration:'60',length:'60',mode:'classic',errors:'free',custom:'',topic:'everyday',targets:['accents'],excluded:'',bots:'0',speedGoal:''} };
const t = (fr,en) => state.locale === 'fr' ? fr : en;
const esc = value => String(value).replace(/[&<>"']/g, char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const icons = {arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',moon:'<path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-15a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5"/>',key:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M6 9h.01M10 9h.01M14 9h.01M18 9h.01M8 15h8"/>',check:'<path d="m5 12 4 4L19 6"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V4H4v12h4"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',focus:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5"/><circle cx="12" cy="12" r="3"/>',chart:'<path d="M4 4v16h16M7 14l4-5 4 3 5-7"/>',link:'<path d="m9 15 6-6m-4-4 2-2a5 5 0 0 1 7 7l-2 2m-5 7-2 2a5 5 0 0 1-7-7l2-2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>'};
const icon = name => `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.key}</svg>`;
const pages = [
 ['home','accueil','Accueil','Home',['normal','empty']],['rooms','courses','Courses publiques','Public races',['normal','empty','loading','error']],['join','rejoindre','Rejoindre par code','Join by code',['normal','error']],['auth','connexion','Connexion','Sign in',['normal','error','oauth-wait','oauth-error','session-expired']],['register','inscription','Compte local','Local account',['normal','error']],['guest','invite','Mode invité','Guest mode',['normal','error']],['create','creation','Créer une salle','Create a room',['normal','private','arcade','error']],['lobby','salon','Salon','Lobby',['normal','host','private','empty','crowd','reconnect','transfer']],['invitation','invitation','Invitation privée','Private invitation',['normal','expired','used','invalid']],['countdown','depart','Départ commun','Countdown',['normal','reconnect']],['race','course','Course','Race',['normal','blocking','arcade','reconnect','interrupted','finished','timeout','afk','energy-empty','energy-ready','energy-active','energy-ended']],['spectator','spectateur','Spectateur','Spectator',['normal','crowd','reconnect']],['results','resultats','Résultats','Results',['normal','host','arcade','empty','few','history']],['practice','entrainement','Entraînement','Practice',['normal','error']],['profile','profil','Profil & progression','Profile & progress',['normal','empty','guest']],['history','historique','Historique','History',['normal','empty','guest']],['preferences','preferences','Préférences','Preferences',['normal']],['help','aide','Comment jouer','How to play',['normal']],['unavailable','indisponible','Accès indisponible','Unavailable',['normal','closed','excluded','interrupted','full','admission']],['global-map','touches','Heatmap globale','Global heatmap',['normal','empty','guest']]
];
const scenarioNames = {'oauth-wait':['Connexion en cours','Connecting'],'oauth-error':['Connexion refusée','Connection failed'],'session-expired':['Session expirée','Session expired'],full:['Salle complète','Room full'],admission:['Admission refusée','Admission denied'],finished:['Terminé · attente du groupe','Finished · waiting for group'],timeout:['Temps écoulé','Time expired'],afk:['Départ pour inactivité','Left due to inactivity'],'energy-empty':['Énergie insuffisante','Not enough energy'],'energy-ready':['Capacité disponible','Ability ready'],'energy-active':['Capacité en cours','Ability active'],'energy-ended':['Capacité terminée','Ability ended'],few:['Deux concurrents','Two competitors'],history:['Détail historique','History detail'],normal:['Aperçu principal','Main view'],empty:['État vide','Empty'],loading:['Chargement','Loading'],error:['Erreur','Error'],host:['Vue hôte','Host view'],private:['Salle privée','Private room'],arcade:['Mode arcade','Arcade mode'],crowd:['Classe · 30 personnes','Class · 30 people'],reconnect:['Reconnexion','Reconnecting'],transfer:['Hôte transféré','Host transferred'],expired:['Lien expiré','Expired link'],used:['Lien déjà utilisé','Used link'],invalid:['Lien inconnu','Unknown link'],blocking:['Erreur bloquante','Blocking errors'],interrupted:['Course annulée','Cancelled race'],guest:['Session invitée','Guest session'],closed:['Salle fermée','Closed room'],excluded:['Accès retiré','Access removed']};
const pageMeta = () => pages.find(p=>p[0]===state.page)||pages[0];
const link = (page,label,klass='subtle') => `<a class="${klass}" href="#${pages.find(p=>p[0]===page)[1]}">${label}</a>`;
const action = (key,label,klass='subtle',extra='') => `<button class="${klass}" data-action="${key}" ${extra}>${label}</button>`;
const heading = (eyebrow,title,desc,actions='') => `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1 id="page-title">${title}</h1><p class="page-lead">${desc}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
const note = (title,text,type='') => `<div class="notice ${type}"><strong>${title}</strong>${text}</div>`;
const field = (id,label,type='text',value='',help='',extra='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${help?`aria-describedby="${id}-help"`:''} ${extra}>${help?`<span class="field-note" id="${id}-help">${help}</span>`:''}</div>`;
const select = (id,label,choices,value)=>`<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}">${choices.map(([v,f,e])=>`<option value="${v}" ${String(value)===v?'selected':''}>${t(f,e||f)}</option>`).join('')}</select></div>`;
const chip = (label,klass='')=>`<span class="badge ${klass}">${label}</span>`;
const empty = (symbol,title,desc,actions='')=>`<div class="box empty-state"><div class="empty-symbol" aria-hidden="true">${symbol}</div><h2>${title}</h2><p class="page-lead" style="margin-left:auto;margin-right:auto">${desc}</p><div class="actions">${actions}</div></div>`;
const metrics = values=>`<div class="metric-grid">${values.map(([value,label])=>`<div class="box metric-box"><div class="metric"><strong>${value}</strong><span>${label}</span></div></div>`).join('')}</div>`;
const scene = ()=>`<div class="key-scene" aria-hidden="true"><span class="scene-key key-a">A</span><span class="scene-key key-z">Z</span><span class="scene-sticker">${t('À TES TOUCHES !','ON YOUR KEYS!')}</span><span class="scene-spark">✳</span></div>`;
function joinForm() {return `<form id="join-form" novalidate><div class="field"><label for="room-code">${t('Le code de ton groupe','Your group code')}</label><input class="join-code" id="room-code" name="code" aria-invalid="${state.scenario==='error'}" placeholder="K7M2PX" maxlength="12" autocomplete="off" aria-describedby="code-help code-error" value="${state.scenario==='error'?'ABC123':''}"><span class="field-note" id="code-help">${t('Pour cette maquette, essaie K7M2PX.','For this prototype, try K7M2PX.')}</span><span class="form-error" id="code-error" aria-live="polite">${state.scenario==='error'?t('Ce code ne correspond à aucune salle active.','This code does not match an active room.'):''}</span></div><button class="primary full" type="submit">${t('Rejoindre le groupe','Join the group')} ${icon('arrow')}</button></form>`;}
function homePage() {return `<div class="home-hero"><div><p class="eyebrow">${t('Le plaisir de jouer. Le rythme de progresser.','The joy of playing. The rhythm of progress.')}</p><h1 id="page-title">${t('Ton clavier.<br><span>Toute une arène.</span>','Your keyboard.<br><span>A whole arena.</span>')}</h1><p class="page-lead">${t('Retrouve ton groupe, défie tes amis et trouve ton rythme. Chaque touche te fait avancer.','Meet your group, challenge your friends and find your rhythm. Every key moves you forward.')}</p><div class="actions">${action('quick',icon('bolt')+' '+t('Course rapide','Quick race'),'primary')}${link('practice',t('M’entraîner','Practice'),'subtle')}</div><div class="hero-marks"><span>${icon('people')} ${t('En groupe ou avec des bots','With friends or bots')}</span><span>${icon('chart')} ${t('Vitesse + précision','Speed + accuracy')}</span></div><div class="hero-playground">${scene()}</div></div><div class="join-card"><p class="eyebrow">${t('Le groupe t’attend','Your group is waiting')}</p><h2>${t('À vos touches.<br>Prêts ? Partez.','On your keys.<br>Ready? Go.')}</h2><p>${t('Tu as reçu un code ? Ta place est juste ici.','Got a code? Your place is right here.')}</p>${joinForm()}<div class="join-divider"></div><div class="actions">${action('create',icon('people')+' '+t('Créer ma salle','Create my room'),'subtle full')}</div><p class="small" style="margin-top:12px">${t('Un compte pour créer. Un pseudo suffit pour rejoindre.','An account to create. A nickname to join.')}</p></div></div><div class="section-heading"><h2>${t('Une course. Trois façons de progresser.','One race. Three ways to improve.')}</h2></div><div class="cards-grid">${[[t('Joue ensemble','Play together'),t('Un code, un départ commun et ton groupe à l’écran.','One code, one shared start and your group on screen.'),'var(--pink)','01','people'],[t('Trouve ton rythme','Find your rhythm'),t('Un texte stable. Des erreurs claires. Toute ton attention sur la frappe.','Stable text. Clear mistakes. Your attention on typing.'),'var(--lavender)','02','key'],[t('Vois tes progrès','See your progress'),t('Vitesse, précision et touches à travailler après chaque course.','Speed, accuracy and keys to practice after every race.'),'var(--accent)','03','chart']].map(([title,desc,color,n,i])=>`<div class="box feature-card"><div class="feature-number"><div class="avatar" style="--avatar:${color}">${icon(i)}</div><span>${n}</span></div><h3>${title}</h3><p class="small">${desc}</p></div>`).join('')}</div><div class="notice" style="margin-top:28px">${t('Tout le monde peut accueillir son groupe : élèves, enseignants et amis. Aucun rôle scolaire particulier.','Everyone can host a group: students, teachers and friends. No special school role.')}</div>`;}
const publicRooms = [{name:'Le sprint des mots',lang:'fr',mode:'classic',people:'5 / 30',color:'var(--pink)',glyph:'é',active:false},{name:'Word sprint',lang:'en',mode:'classic',people:'12 / 30',color:'var(--sky)',glyph:'W',active:false},{name:'La touche surprise',lang:'fr',mode:'arcade',people:'8 / 30',color:'var(--lavender)',glyph:'✳',active:true}];
function roomCards(list) {return list.map(r=>`<article class="box room-card"><div class="card-art" style="--tint:${r.color}"><span aria-hidden="true">${r.glyph}</span>${chip(r.active?t('En course','Racing'):t('Attend le départ','Waiting'),'badge-host')}</div><h2>${r.name}</h2><p class="small">${t('Une salle publique pour jouer ensemble.','A public room to play together.')}</p><div class="room-meta">${chip(r.lang==='fr'?t('Français','French'):t('Anglais','English'))}${chip(r.mode==='classic'?t('Classique','Classic'):t('Arcade','Arcade'))}${chip(r.people+' '+t('personnes','people'))}${chip('60 '+t('secondes','seconds'))}</div><div class="actions">${action(r.active?'watch':'join-public',r.active?t('Regarder','Watch'):t('Rejoindre','Join'),'primary',`data-room-name="${r.name}" data-room-lang="${r.lang}" data-room-mode="${r.mode}"`)}</div></article>`).join('');}
function roomsPage() {let content= state.scenario==='loading'?`<div role="status"><p>${t('Recherche des salles en cours…','Looking for rooms…')}</p><div class="skeleton-grid" aria-hidden="true">${[1,2,3].map(()=>'<div class="box"><div class="skeleton large"></div><div class="skeleton"></div><div class="skeleton short"></div></div>').join('')}</div></div>`:state.scenario==='error'?empty('!',t('Les salles prennent une pause.','Rooms are taking a break.'),t('Impossible de charger la liste. Tu peux réessayer ou t’entraîner.','The list could not load. Try again or practice.'),action('normal',t('Réessayer','Try again'),'primary')+link('practice',t('M’entraîner','Practice'))):state.scenario==='empty'?empty('…',t('Le prochain départ peut être le tien.','The next race can start with you.'),t('Aucune salle publique n’attend pour l’instant. Crée un groupe avec un compte ou essaie les bots.','No public room is waiting right now. Create one with an account or try the bots.'),action('create',t('Créer une salle','Create a room'),'primary')+link('practice',t('M’entraîner','Practice'))):`<div class="cards-grid" id="public-rooms">${roomCards(publicRooms)}</div><p class="small" style="margin-top:18px">${t('Salles d’exemple. Les salles privées et semi-publiques ne sont pas répertoriées ici.','Example rooms. Private and code-only rooms are not listed here.')}</p>`;return heading(t('Ensemble, ça va plus vite','Better together'),t('Trouve ton groupe.','Find your group.'),t('Rejoins une course publique en attente ou regarde une course déjà lancée.','Join a waiting public race or watch one that has started.'),action('quick',icon('bolt')+t('Course rapide','Quick race'),'primary')+action('create',t('Créer','Create')))+`<div class="filter-bar">${select('filter-lang',t('Langue du texte','Text language'),[['all','Toutes','All'],['fr','Français','French'],['en','Anglais','English']],'all')}${select('filter-mode',t('Mode','Mode'),[['all','Tous','All'],['classic','Classique','Classic'],['arcade','Arcade','Arcade']],'all')}${select('filter-state',t('État','Status'),[['all','Tous','All'],['waiting','En attente','Waiting'],['racing','En course','Racing']],'all')}</div>${content}`;}
function joinPage() {return heading(t('Retrouver ton groupe','Find your group'),t('Six signes. Une place pour toi.','Six characters. A place for you.'),t('Le code rejoint une salle semi-publique. Pour une salle privée, ouvre le lien personnel envoyé par l’hôte.','A code joins an unlisted room. For a private room, open your personal invitation link.'))+`<div class="box form-box">${joinForm()}<div class="divider-label">${t('Pas de code ?','No code?')}</div>${link('rooms',t('Voir les courses publiques','Browse public races'),'subtle full')}</div>`;}
function authPage() {if(['oauth-wait','oauth-error','session-expired'].includes(state.scenario))return authStatePage();return `<div class="auth-layout"><div class="auth-story"><p class="eyebrow">${t('Ta prochaine course commence ici','Your next race starts here')}</p><h1 id="page-title">${t('Une place.<br>Tout ton progrès.','Your place.<br>All your progress.')}</h1><p class="page-lead">${t('Avec un compte, crée tes salles et retrouve ton historique. Sans compte, rejoins simplement le groupe.','With an account, create rooms and keep your history. Without one, just join the group.')}</p>${scene()}<p class="small">${t('Les mêmes droits pour les élèves, les enseignants et les amis.','The same permissions for students, teachers and friends.')}</p></div><div class="box"><h2>${t('Heureux de te retrouver.','Good to see you.')}</h2><p class="small">${t('Choisis comment entrer.','Choose how to join.')}</p>${state.pending==='create'?note(t('Un compte pour accueillir','An account to host'),t('Connecte-toi avant de configurer ta salle.','Sign in before configuring your room.')):''}${action('provider-discord','<span class="provider-symbol" aria-hidden="true">D</span>'+t('Continuer avec Discord','Continue with Discord'),'subtle provider-button')}${action('provider-github','<span class="provider-symbol" aria-hidden="true">GH</span>'+t('Continuer avec GitHub','Continue with GitHub'),'subtle provider-button')}<div class="divider-label">${t('ou ton compte local','or your local account')}</div><form id="login-form" novalidate>${field('login-name',t('Nom d’utilisateur','Username'),'text','', '', 'autocomplete="off" required')}${field('login-password',t('Mot de passe','Password'),'password','','','autocomplete="off" required')}<span class="form-error" id="login-error" aria-live="polite">${state.scenario==='error'?t('Nom d’utilisateur ou mot de passe incorrect.','Incorrect username or password.'):''}</span><button type="submit" class="primary full">${t('Me connecter','Sign in')} ${icon('arrow')}</button></form><div class="actions" style="margin-top:14px">${link('register',t('Créer un compte local','Create a local account'),'ghost')}${link('guest',t('Continuer en invité','Continue as a guest'),'ghost')}</div><p class="small" style="margin-top:20px;font-size:12px">${t('Accès simulés : les boutons restent dans cette maquette. Utilise des valeurs d’exemple pour les champs.','Simulated access: buttons stay within this prototype. Use example values in the fields.')}</p></div></div>`;}
function registerPage() {return heading(t('Ton compte local','Your local account'),t('Prêt à garder ton rythme ?','Ready to keep your rhythm?'),t('Un nom d’utilisateur et un mot de passe. Ton historique te suit quand tu te reconnectes.','A username and password. Your history follows you when you sign in again.'))+`<div class="box form-box">${note(t('Sans courriel ni récupération','No email or recovery'),t('Si tu oublies ce mot de passe, ce compte ne pourra pas être récupéré. Discord et GitHub restent des alternatives.','If you forget this password, this account cannot be recovered. Discord and GitHub are alternatives.'))}<form id="register-form" novalidate>${field('register-name',t('Nom d’utilisateur','Username'),'text','',t('Dans cette maquette, choisis un pseudo d’exemple.','In this prototype, choose an example nickname.'),'required autocomplete="off" maxlength="24"')}${field('register-password',t('Mot de passe','Password'),'password','','','required autocomplete="off"')}${field('register-confirm',t('Confirmer le mot de passe','Confirm password'),'password','','','required autocomplete="off"')}<span id="register-error" class="form-error" aria-live="polite">${state.scenario==='error'?t('Ce nom d’utilisateur est déjà pris.','This username is already taken.'):''}</span><button class="primary full" type="submit">${t('Créer mon compte d’exemple','Create example account')}</button></form><div class="actions" style="margin-top:14px">${link('auth',t('Revenir à la connexion','Back to sign in'),'ghost')}</div><p class="small" style="margin-top:14px">${t('Aucun compte réel ni mot de passe enregistré.','No real account or password is saved.')}</p></div>`;}
function guestPage() {return heading(t('Entrer sans compte','Join without an account'),t('Ton pseudo. Ta place.','Your nickname. Your place.'),t('Rejoins une course publique, un groupe par code ou une invitation privée.','Join a public race, a group by code or a private invitation.'))+`<div class="box form-box"><div class="avatar" aria-hidden="true" style="--avatar:var(--accent);width:68px;height:68px;font-size:34px;margin-bottom:22px">T</div><form id="guest-form" novalidate>${field('guest-name',t('Ton pseudonyme','Your nickname'),'text','',t('Visible par les personnes de la salle.','Visible to the people in the room.'),'required maxlength="24" autocomplete="off"')}<span id="guest-error" class="form-error" aria-live="polite">${state.scenario==='error'?t('Choisis un pseudonyme pour entrer.','Choose a nickname to join.'):''}</span><button class="primary full" type="submit">${t('C’est parti','Let’s go')} ${icon('arrow')}</button></form><div class="notice" style="margin-top:22px;margin-bottom:0"><strong>${t('Le temps d’une session','For this session')}</strong>${t('Tes résultats restent accessibles pendant ta session active. Un compte est nécessaire pour créer une salle et conserver un historique permanent.','Your results remain available during your active session. An account is required to create a room and keep permanent history.')}</div></div>`;}
function createPage() {if(state.identity!=='account') return heading(t('Accueillir ton groupe','Host your group'),t('Un compte, puis ta salle.','An account, then your room.'),t('Les invités peuvent participer. La création d’une salle exige un compte.','Guests can participate. Creating a room requires an account.'))+empty('+',t('Garde tes réglages pour la prochaine étape.','Your settings come next.'),t('Connecte-toi pour choisir les règles et accueillir ton groupe.','Sign in to choose the rules and host your group.'),action('auth-create',t('Me connecter pour créer','Sign in to create'),'primary')+link('rooms',t('Rejoindre une course','Join a race')));const room=state.scenario==='error'?{...state.room,content:'custom',custom:'Un défi pour le groupe.',excluded:'é'}:state.room;let access=state.scenario==='private'?'private':room.access,mode=state.scenario==='arcade'?'arcade':room.mode;return heading(t('À toi de donner le départ','Your turn to start the race'),t('Prépare ton terrain de jeu.','Set up your playground.'),t('Choisis qui entre, ce que le groupe tape et les règles du départ.','Choose who joins, what your group types and the rules.'))+`<div class="content-grid"><form id="create-form" class="box" novalidate><section class="editor-section"><h2><span class="step-dot">01</span>${t('Le groupe','The group')}</h2>${field('room-name',t('Nom de la salle','Room name'),'text',room.name,'','required maxlength="60"')}<fieldset class="field"><legend>${t('Qui peut rejoindre ?','Who can join?')}</legend><div class="choice-grid">${[['public',t('Public','Public'),t('Visible dans les courses','Listed in public races')],['semi',t('Par code','By code'),t('Non répertorié','Unlisted')],['private',t('Privé','Private'),t('Liens personnels uniques','Unique personal links')]].map(([v,title,desc])=>`<label class="choice"><input type="radio" name="access" value="${v}" ${access===v?'checked':''}><span><strong>${title}</strong><small>${desc}</small></span></label>`).join('')}</div></fieldset><p id="access-explanation" class="choice-hint">${icon('link')}<span>${accessText(access)}</span></p></section><section class="editor-section"><h2><span class="step-dot">02</span>${t('Le texte','The text')}</h2><div class="field-row">${select('content-type',t('Type de contenu','Content type'),[['text','Texte cohérent','Coherent text'],['words','Suite de mots','Word list'],['custom','Texte personnalisé','Custom text']],room.content)}${select('content-language',t('Langue du texte','Text language'),[['fr','Français','French'],['en','Anglais','English']],room.language)}</div><div class="field" id="custom-field" ${room.content==='custom'?'':'hidden'}><label for="custom-text">${t('Ton texte','Your text')}</label><textarea id="custom-text" aria-describedby="custom-text-help" placeholder="${t('Écris un texte que tu as le droit de partager…','Write a text you have permission to share…')}">${esc(room.custom)}</textarea><span class="field-note" id="custom-text-help">${t('Le groupe tapera exactement ce contenu. Aucun texte généré par IA.','The group will type this content. No AI-generated text.')}</span></div><div class="field-row">${select('text-theme',t('Thème','Topic'),[['everyday','Petites aventures','Small adventures'],['nature','Nature','Nature'],['science','Sciences','Science']],room.topic)}${select('text-length',t('Longueur indicative','Suggested length'),[['30','30 mots','30 words'],['60','60 mots','60 words'],['100','100 mots','100 words']],room.length)}</div><fieldset><legend class="small">${t('À pratiquer','Practice targets')}</legend><div class="check-group">${[['accents','Accents','Accents'],['punctuation','Ponctuation','Punctuation'],['numbers','Chiffres','Numbers'],['special','Caractères spéciaux','Special characters']].map(([id,fr,en])=>`<label><input type="checkbox" name="target" value="${id}" ${(room.targets||['accents']).includes(id)?'checked':''}>${t(fr,en)}</label>`).join('')}</div></fieldset>${field('excluded-characters',t('Caractères à exclure','Excluded characters'),'text',room.excluded||'',t('Exemple : @ # %. Le contenu devra être vérifié avant le départ.','Example: @ # %. Content must be checked before starting.'))}<p class="small">${t('La langue du texte est indépendante de l’interface. Thème, longueur et cibles illustrent les réglages futurs; le contenu prédéfini reste un court exemple fixe.','Text language is independent from the interface. Topic, length and targets illustrate future settings; predefined content remains a short fixed sample.')}</p></section><section class="editor-section"><h2><span class="step-dot">03</span>${t('Les règles','The rules')}</h2><div class="field-row">${select('race-duration',t('Limite de temps','Time limit'),[['none','Sans limite','No time limit'],['30','30 secondes','30 seconds'],['60','60 secondes','60 seconds'],['120','120 secondes','120 seconds']],room.duration)}${select('race-errors',t('Une erreur…','A mistake…'),[['free','Est comptée, je continue','Is counted, I continue'],['block','Doit être corrigée','Must be corrected']],room.errors)}</div><div class="field-row">${select('race-mode',t('Mode de jeu','Game mode'),[['classic','Classique · sans bonus','Classic · no bonuses'],['arcade','Arcade · rattrapage','Arcade · catch-up']],mode)}${field('speed-target',t('Objectif MPM (facultatif)','WPM goal (optional)'),'number',room.speedGoal||'',t('Un repère de pratique, pas une condition de victoire.','A practice target, not a win condition.'),'min="1" max="250"')}</div><details class="accordion"><summary>${t('Bots et règles de classement','Bots and scoring rules')}</summary><div>${select('room-bots',t('Bots de départ','Starting bots'),[['0','Aucun','None'],['1','1 bot doux','1 gentle bot'],['2','2 bots variés','2 varied bots']],room.bots||'0')}<p class="small">${t('En mode classique, la vitesse et la précision alimenteront une formule commune. La pénalité d’erreurs reste à valider. La course termine quand tous les actifs ont fini ou quand le temps expire.','In classic mode, speed and accuracy will feed a shared formula. Error penalties need validation. The race ends when all active players finish or time runs out.')}</p><p class="small">${t('Arcade : deux capacités de rattrapage proposées, avec mesures pédagogiques séparées du résultat de jeu.','Arcade: two proposed catch-up abilities, with learning metrics separate from game results.')}</p></div></details></section><span class="form-error" id="create-error" aria-live="polite">${state.scenario==='error'?t('Le texte contient un caractère que tu as exclu.','The text contains an excluded character.'):''}</span><div class="actions" style="margin-top:24px"><button class="primary" type="submit">${t('Créer le salon d’exemple','Create example lobby')} ${icon('arrow')}</button>${link('home',t('Annuler','Cancel'),'ghost')}</div></form><aside class="stack editor-aside"><div class="box tinted"><p class="eyebrow">${t('Un aperçu avant le départ','A preview before starting')}</p><h2 id="config-preview-title">${esc(room.name)}</h2><p class="preview-text" id="config-preview-text">${exerciseText()}</p><div class="metadata" id="config-preview-meta" id="config-preview-meta">${chip(room.language==='fr'?t('Français','French'):t('Anglais','English'))}${chip(mode==='classic'?t('Classique','Classic'):'Arcade')}</div></div><div class="box quiet"><h3>${t('Tout le monde voit les règles.','Everyone sees the rules.')}</h3><p class="small">${t('Les membres les consultent au salon. Seul l’hôte les modifie; elles seront figées au départ.','Members read them in the lobby. Only the host changes them; they freeze when the race starts.')}</p></div></aside></div>`;}
function accessText(access) {return access==='private'?t('Un lien individuel à usage unique par personne. Aucun code public ou QR d’accès.','One personal single-use link per person. No room code or entry QR.'):access==='public'?t('Ta salle apparaît dans la liste publique. Tout le monde peut demander à rejoindre.','Your room appears in the public list. Anyone can join.'):t('Un code pour ton groupe. La salle n’apparaît pas dans la liste publique.','One code for your group. The room is not in the public list.');}
const demoName=name=>name===state.pseudo?'Solstice':name;
const names = ['Nova','Toi','Milo','Lune','Pixel','Bot doux','Jules','Aster','Lia','Romy','Alex','Sacha','Éli','Lou','Noa','Sam','Charlie','Max','Cam','Kim','Zoé','Iris','Félix','Jade','Alix','Robin','Eden','Maël','Nico','Sol'];
function lobbyPage() {const privateRoom=state.scenario==='private'||state.room.access==='private';const host=state.host||state.scenario==='host'||state.scenario==='transfer';const selfName=state.identity==='anonymous'?t('Toi','You'):state.pseudo;const otherHost=demoName('Nova');const crowd=state.scenario==='crowd';const count=state.scenario==='empty'?1:crowd?30:6;const title=state.room.name;let people = names.slice(0,count).map((name,i)=>{const self=i===(count===1?0:1);let n=self?selfName:i===0?otherHost:demoName(name);if(state.scenario==='transfer'&&i===0)n='Sol';let role=i===0?(host?self?t('Hôte','Host'):t('Participant','Player'):t('Hôte','Host')):i===4?t('Spectateur','Spectator'):i===5?t('Bot · simulé','Bot · simulated'):t('Participant','Player');if(self&&host)role=t('Hôte','Host');let ready=self?state.ready:i<4;return crowd?`<div class="player-row"><div class="avatar" style="--avatar:${['var(--sky)','var(--accent)','var(--coral)','var(--lavender)'][i%4]}" aria-hidden="true">${esc(n[0])}</div><div><strong>${esc(n)}${self?' · '+t('toi','you'):''}</strong><div class="small">${role}</div></div>${chip(i===4?t('Observe','Watching'):ready?t('Prêt','Ready'):t('En attente','Waiting'),ready?'badge-ready':'')}</div>`:`<div class="player ${self?'player-self':''}" data-ready="${self&&state.ready}"><div class="avatar" aria-hidden="true" style="--avatar:${['var(--sky)','var(--accent)','var(--coral)','var(--lavender)'][i%4]}">${esc(n[0])}</div><strong>${esc(n)}</strong><span class="player-role">${role}</span>${chip(i===4?t('Observe','Watching'):i===5?t('Exemple','Example'):ready?'✓ '+t('Prêt','Ready'):t('En attente','Waiting'),ready?'badge-ready':'')}</div>`;}).join('');let notice=state.scenario==='reconnect'?note(t('Reconnexion en cours…','Reconnecting…'),t('Ta place et le dernier état confirmé sont conservés. Les commandes attendent la connexion.','Your place and last confirmed state are kept. Controls wait for the connection.')):state.scenario==='transfer'?note(t('Tu prends le relais.','You take over.'),t('L’hôte précédent a quitté. Tu es maintenant l’hôte de cette salle. Ce rôle ne crée pas de droit permanent.','The previous host left. You now host this room. This role gives no permanent permissions.'),'colorful'):'';return heading(t('Ton groupe, au même endroit','Your group, in one place'),t('Le départ se prépare.','Getting ready to race.'),t('Vérifie les règles, retrouve ta place et prépare tes doigts.','Check the rules, find your place and get your fingers ready.'),action('leave',t('Quitter la salle','Leave room'),'ghost'))+notice+`<section class="panel room-panel"><div class="panel-top"><div class="room-title"><span class="room-symbol">${icon('key')}</span><div><h2>${esc(title)}</h2><p class="small">${privateRoom?t('Privé · invitations personnelles','Private · personal invitations'):state.room.access==='public'?t('Public','Public'):t('Semi-public · par code','Unlisted · by code')} · ${t('Hôte','Host')} : ${host?esc(selfName):otherHost}</p></div></div><div class="room-summary"><b class="room-count">${String(count).padStart(2,'0')}</b><div class="small">${t('personnes au salon','people in the lobby')}<br>${count===1?(state.ready?1:0):state.ready?4:3} / ${count===1?1:crowd?29:5} ${t('joueurs prêts','players ready')}</div></div></div><div class="lobby-grid"><div class="lobby-main"><div class="lobby-banner"><div><strong>${t('La prochaine touche, c’est ensemble.','The next key is a shared one.')}</strong><span>${t('Le groupe se rassemble. Ta place est réservée.','Your group is gathering. Your place is saved.')}</span></div><span class="banner-spark" aria-hidden="true">✳</span></div><div class="invite-strip">${!privateRoom&&state.room.access==='public'?`<div><p class="eyebrow">${t('Ouvert au groupe','Open to the group')}</p><p class="small">${t('Cette salle apparaît dans les courses publiques.','This room appears in public races.')}</p></div>${link('rooms',t('Voir les courses publiques','View public races'),'subtle')}`:privateRoom?`<div><p class="eyebrow">${t('Un lien par personne','One link per person')}</p><p class="small">${t('L’accès est réservé aux personnes invitées.','Access is reserved for invited people.')}</p></div><div class="actions">${host?action('invite-private',icon('link')+t('Gérer les invitations','Manage invitations')):chip(t('Invitation personnelle','Personal invitation'))}</div>`:`<div><p class="eyebrow">${t('Le code du groupe','Group code')}</p><div class="lobby-code"><span class="code">K7M2PX</span>${action('copy-code',icon('copy'),'subtle copy-button',`aria-label="${t('Copier le code','Copy code')}"`)}</div></div><div class="actions">${action('invite-code',icon('people')+t('Inviter le groupe','Invite the group'))}</div>`}</div><div class="section-heading"><h3>${t('Dans les starting-blocks','At the starting line')}</h3><span class="small">${crowd?'30':count} ${t('personnes','people')}</span></div><div class="${crowd?'room-people':'player-grid'}" ${crowd?'tabindex="0" aria-label="'+t('Les 30 membres','All 30 members')+'"':''}>${people}</div>${host?`<div class="player-tools">${action('manage-people',t('Gérer les rôles','Manage roles'))}${action('add-bot',t('Ajouter un bot','Add a bot'))}</div>`:''}</div><aside class="lobby-aside"><div class="exercise-preview"><p class="eyebrow">${t('Le texte de cette course','This race’s text')}</p><h3>${t('Les petites victoires','Small victories')}</h3><p>${esc(exerciseText().slice(0,65))}…</p><span class="exercise-key" aria-hidden="true">${state.room.language==='fr'?'é':'W'}</span></div><div class="settings">${[[t('Langue du texte','Text language'),state.room.language==='fr'?t('Français','French'):t('Anglais','English')],[t('Durée','Duration'),state.room.duration==='none'?t('Sans limite','No limit'):state.room.duration+' '+t('secondes','seconds')],[t('Erreurs','Errors'),state.room.errors==='block'?t('À corriger','Must correct'):t('Non bloquantes','Non-blocking')],[t('Mode','Mode'),state.room.mode==='arcade'?'Arcade':t('Classique · sans bonus','Classic · no bonuses')]].map(([label,val])=>`<div class="setting"><span>${label}</span><strong>${val}</strong></div>`).join('')}</div>${host?action('edit-config',icon('settings')+t('Modifier les règles','Edit rules'),'subtle full'):note(t('Réglages de l’hôte','Host settings'),t('Tu les consultes ici. Ils seront figés au départ.','Read them here. They freeze when the race starts.'))}<div class="ready-action" style="margin-top:20px">${action(host?'start':'ready',(state.ready?icon('check'):'')+(host?t('Lancer le départ','Start countdown'):state.ready?t('Prêt ! Modifier mon état','Ready! Change my status'):t('Je suis prêt','I’m ready')),'primary full',`aria-pressed="${state.ready}" ${state.scenario==='reconnect'?'disabled':''}`)}<p class="small">${host?t('Départ d’exemple. Le serveur vérifiera les conditions réelles.','Example start. The server will check real conditions.'):t(otherHost+' donne le départ quand le groupe est prêt.',otherHost+' starts when the group is ready.')}</p></div></aside></div><div class="lobby-bottom"><span class="status">${icon('clock')}${state.ready?t('Tu es prêt. Le groupe attend le départ.','You’re ready. The group is waiting for the start.'):t('Ta place est là. Le groupe attend le départ.','Your place is saved. The group is waiting for the start.')}</span>${action('preview-start',t('Voir le départ d’exemple','View example countdown'),'ghost')}</div></section>`;}
function invitationPage() {const bad=['expired','used','invalid'].includes(state.scenario);if(bad) return heading(t('Invitation personnelle','Personal invitation'),t('Ce lien ne peut plus t’accueillir.','This link cannot let you in.'),t('Une invitation privée appartient à une personne et ne fonctionne qu’une fois.','A private invitation belongs to one person and works once.'))+empty('↗',state.scenario==='expired'?t('Invitation expirée','Expired invitation'):state.scenario==='used'?t('Invitation déjà utilisée','Invitation already used'):t('Invitation introuvable','Invitation not found'),t('Demande un nouveau lien personnel à l’hôte. Aucun code de salle ne remplace cet accès.','Ask the host for a new personal link. A room code cannot replace this access.'),link('home',t('Revenir à l’accueil','Back home'),'primary'));return heading(t('Une place réservée','A place saved for you'),t('Ton groupe t’a invité.','Your group invited you.'),t('Ouvrir cette page ne consomme pas l’invitation. Elle sera utilisée au moment de rejoindre.','Opening this page does not consume the invitation. It is used when you join.'))+`<div class="box form-box"><div class="box tinted" style="box-shadow:none;margin-bottom:22px"><p class="eyebrow">${t('Privé · lien personnel','Private · personal link')}</p><h2>${t('La course du vendredi','Friday race')}</h2><p>${t('Nova t’attend avec son groupe.','Nova is waiting for you with the group.')}</p><div class="metadata">${chip(t('Français','French'))}${chip('60 '+t('secondes','seconds'))}${chip(t('Classique','Classic'))}</div></div>${note(t('Une invitation. Une entrée.','One invitation. One entry.'),t('Ce lien est individuel et à usage unique. Ne le partage pas avec le groupe. La validité exacte reste à fixer.','This link is personal and single-use. Do not share it with the group. Its exact validity period is still to be decided.'))}<div class="actions">${action('accept-invite',t('Rejoindre avec cette invitation','Join with this invitation'),'primary full')}${action('auth-invite',t('Me connecter d’abord','Sign in first'),'ghost full')}</div></div>`;}
function countdownPage() {return heading(t('Le même départ pour tout le groupe','One start for the whole group'),t('À tes touches.','On your keys.'),t('Le texte et les règles sont figés. Le départ réel sera synchronisé par le serveur.','Text and rules are frozen. The real start will be synchronized by the server.'))+(state.scenario==='reconnect'?note(t('Ta place est conservée.','Your place is saved.'),t('La connexion est interrompue. Attends le dernier état confirmé du serveur.','Connection interrupted. Wait for the last confirmed server state.')):'')+`<div class="panel countdown-card"><p class="eyebrow">${esc(state.room.name)}</p><h2>${t('Trouve ta position. Prends ton rythme.','Find your position. Find your rhythm.')}</h2><div class="countdown-number" aria-label="${t('Exemple de compte à rebours : 3','Example countdown: 3')}">3</div><p class="small">${t('Compte à rebours figé pour étudier le design.','Frozen countdown to review the design.')}</p><div class="metadata">${chip(state.room.language==='fr'?t('Français','French'):t('Anglais','English'))}${chip(state.room.mode==='arcade'?'Arcade':t('Classique','Classic'))}${chip(t('Collage désactivé','Paste disabled'))}</div><div class="actions" style="justify-content:center;margin-top:24px">${action('go-race',t('Voir la course d’exemple','View example race'),'primary')}${action('watch',t('Voir comme spectateur','View as spectator'))}</div></div>`;}
function exerciseText() {if(state.room.content==='words')return state.room.language==='en'?'rhythm group key sprint word gentle focus steady practice line':'rythme groupe touche course mot calme regard précis exercice ligne';if(state.room.content==='custom'&&state.room.custom) return state.room.custom;return state.room.language==='en'?'Every key brings you closer to the next challenge. Find your rhythm and keep your eyes on the line.':'Chaque touche te rapproche du prochain défi. Trouve ton rythme et garde les yeux sur la ligne.';}
function lane(name,rank,progress,color,self=false) {return `<div class="lane" ${self?'id="live-self-lane"':''}><div class="avatar" aria-hidden="true" style="--avatar:${color}">${esc(name[0])}</div><span class="lane-name ${self?'you':''}"><span class="lane-rank">${String(rank).padStart(2,'0')}</span><strong>${esc(name)}</strong></span><div class="lane-line" style="--progress:${progress}%;--lane-color:${self?'var(--player-line)':color==='var(--sky)'?'var(--blue)':color==='var(--coral)'?'var(--error)':'var(--player-line)'}" role="progressbar" ${self?'id="live-progress"':''} aria-label="${esc(name)} · ${t('progression','progress')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}"><div class="lane-fill"></div><span class="lane-cursor"></span></div><span class="percent" ${self?'id="live-percent"':''}>${progress} %</span></div>`;}
function racePage(spectator=false) {if(['finished','timeout','afk'].includes(state.scenario))return raceEndState();if(state.scenario==='interrupted')return heading(t('La course s’arrête ici','The race stops here'),t('Une nouvelle ligne de départ.','A new starting line.'),t('Le serveur a interrompu cette course. Aucun classement ni victoire ne sera attribué.','The server interrupted this race. No ranking or win will be awarded.'))+empty('↻',t('Course annulée','Race cancelled'),t('Le groupe peut retourner au salon pour préparer un nouveau départ.','The group can return to the lobby for a new start.'),link('lobby',t('Retour au salon','Back to lobby'),'primary'));let arcade=state.scenario==='arcade'||state.scenario.startsWith('energy-')||state.room.mode==='arcade',block=state.scenario==='blocking'||state.room.errors==='block';return `<div class="race-page">${heading(spectator?t('Voir le groupe en action','Watch your group'):state.practice?t('Entraînement','Practice'):t('La course, à ton rythme','The race, at your rhythm'),spectator?t('Une place aux premières loges.','A front-row seat.'):t('Chaque touche te rapproche.','Every key brings you closer.'),spectator?t('Tu es arrivé après le départ. Tu observes cette manche et pourras jouer à la prochaine.','You arrived after the start. Watch this round and join the next.'):t('La progression et la précision sont locales. Adversaires, minuterie et rangs sont des exemples.','Progress and accuracy are local. Opponents, timer and rankings are examples.'),action('leave',t('Quitter','Leave'),'ghost'))}${state.scenario==='reconnect'?note(t('Reconnexion… ta place reste là.','Reconnecting… your place is saved.'),t('La frappe attend. Le dernier état confirmé demeure visible; aucune progression n’est inventée.','Typing waits. The last confirmed state stays visible; no progress is invented.')):''}<section class="panel"><div class="panel-top race-top"><div><h2>${esc(state.room.name)}</h2><div class="small">${state.room.language==='fr'?t('Texte français','French text'):t('Texte anglais','English text')} · ${arcade?'Arcade':t('Classique','Classic')} · ${block?t('Erreurs à corriger','Correct mistakes'):t('Erreurs comptées','Mistakes counted')}</div></div><div class="actions">${spectator?'':action('focus',icon('focus')+t('Concentration','Focus'),'subtle',`aria-pressed="${state.focus}"`)}${spectator?'':action('reset-race',t('Recommencer','Restart'),'ghost')}</div></div>${arcade?`<div class="arcade-strip"><div><strong>${t('Tempo · capacité de rattrapage proposée','Tempo · proposed catch-up ability')}</strong><div class="small">${t('Frappe correcte → énergie. Disponible surtout en retard.','Correct typing → energy. Available primarily when behind.')}</div><div class="energy" role="meter" aria-label="${t('Énergie d’exemple','Example energy')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${state.scenario==='energy-empty'?'20':state.scenario==='energy-ready'?'100':state.scenario==='energy-active'?'45':state.scenario==='energy-ended'?'0':'70'}"><span style="width:${state.scenario==='energy-empty'?'20':state.scenario==='energy-ready'?'100':state.scenario==='energy-active'?'45':state.scenario==='energy-ended'?'0':'70'}%"></span></div></div><div><span class="small">${state.scenario==='energy-empty'?t('20 / 100 · Continue à taper correctement.','20 / 100 · Keep typing correctly.'):state.scenario==='energy-ready'?t('100 / 100 · Tempo est disponible.','100 / 100 · Tempo is available.'):state.scenario==='energy-active'?t('Effet en cours · exemple figé.','Effect active · frozen example.'):state.scenario==='energy-ended'?t('Effet terminé · recharge par la frappe.','Effect ended · recharge by typing.'):t('70 / 100 · exemple de jauge','70 / 100 · sample meter')}</span>${action('ability',state.scenario==='energy-ready'?t('Activer Tempo · aperçu','Activate Tempo · preview'):t('Voir les capacités','View abilities'),'subtle')}</div></div>`:''}<div class="race-dashboard"><div class="metric-top"><div class="metric"><strong id="live-speed">—</strong><span>${t('MPM · non mesurés ici','WPM · not measured here')}</span></div><div class="metric"><strong id="live-accuracy">${spectator?'—':'—'}</strong><span>${t('Précision locale','Local accuracy')}</span></div></div><div class="timer" aria-label="${t('Minuterie d’exemple','Example timer')}">${icon('clock')} ${state.room.duration==='none'?'∞':Math.floor(Number(state.room.duration)/60).toString().padStart(2,'0')+':'+(Number(state.room.duration)%60).toString().padStart(2,'0')}</div></div><div class="race"><div class="race-rules"><span>${t('Règles figées','Frozen rules')}</span><span>${block?t('Corrige avant de poursuivre','Correct before continuing'):t('Pénalité de classement à valider','Scoring penalty to validate')}</span><span>${t('Collage bloqué','Paste blocked')}</span></div>${spectator?`<div class="box quiet"><h3>${t('Les doigts jouent. Les positions évoluent.','Fingers type. Positions change.')}</h3><p class="small">${t('Le spectateur n’a pas de champ de frappe compétitif. Les pistes ci-dessous montrent un état d’exemple.','A spectator has no competitive typing field. The tracks below show an example state.')}</p></div>`:`<div id="live-text" class="typing-text" aria-hidden="true"></div><p id="live-prompt" class="visually-hidden">${t('Texte à reproduire :','Text to type:')} ${esc(exerciseText())}</p><div class="input-label"><label for="live-input">${t('À toi de jouer','Your turn')}</label><span>${t('Le texte reste stable.','The text stays stable.')}</span></div><div class="typing-field"><input id="live-input" class="typing-input" type="text" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" placeholder="${t('Commence à taper ici…','Start typing here…')}" aria-describedby="live-prompt live-help" ${state.scenario==='reconnect'?'disabled':''}>${icon('key')}</div><div class="helper"><span id="live-help">${block?t('Une faute bloque la progression jusqu’à correction.','A mistake blocks progress until corrected.'):t('Les fautes sont soulignées. Tu peux les corriger.','Mistakes are underlined. You can correct them.')}</span><span id="live-feedback" role="status" aria-live="polite">${t('Essaie quelques mots à ton rythme.','Try a few words at your own pace.')}</span></div>`}</div><div class="tracks"><div class="track-label"><h3>${t('La course autour de toi','The race around you')}</h3>${action('ranking',t('Voir les 30 positions','View all 30 positions'),'ghost')}</div>${lane(demoName('Nova'),1,74,'var(--sky)')}${lane(demoName('Milo'),2,61,'var(--coral)')}${lane(demoName('Lune'),3,55,'var(--accent)')}${spectator?'':lane(state.identity==='anonymous'?t('Toi','You'):state.pseudo,14,0,'var(--accent)',true)}${spectator?'':lane(demoName('Jules'),13,38,'var(--sky)')}${spectator?'':lane(demoName('Aster'),15,31,'var(--coral)')}</div></section><div class="actions" style="justify-content:flex-end">${action('example-results',t('Voir les résultats d’exemple','View example results'),'primary')}</div><p class="small" style="margin-top:16px">${t('Les pistes restent rangées pendant la lecture; leurs chiffres ne constituent pas un classement calculé ici.','Tracks stay in place while reading; their numbers are not a ranking calculated here.')}</p></div>`;}
const heatData = [['é',4,50],['a',2,100],['r',1,90],['t',0,87],['u',0,0]];
function heatmap() {let rows=['1234567890','AZERTYUIOP','QSDFGHJKLM','WXCVBNÉÀÇ'];return `<div class="heatmap" role="img" aria-label="${t('Clavier d’exemple. Les valeurs sont disponibles dans le tableau ci-dessous.','Example keyboard. Values are available in the table below.')}">${rows.map(row=>`<div class="keyboard-row">${[...row].map(key=>{let d=heatData.find(x=>x[0]===key.toLowerCase());let level=d?d[2]===0?'none':d[1]===0?'0':d[1]>=4?'3':d[1]>=2?'2':'1':'none';return `<span class="heat-key" data-level="${level}" aria-hidden="true">${key}<i>${d?(d[2]===0?'—':d[1]):'—'}</i></span>`;}).join('')}</div>`).join('')}</div><div class="heat-legend"><span><i class="legend-color none"></i>${t('— Aucune frappe','— No keystrokes')}</span><span><i class="legend-color" style="background:var(--background)"></i>${t('0 erreur','0 mistakes')}</span><span><i class="legend-color" style="background:var(--sky)"></i>${t('1 erreur','1 mistake')}</span><span><i class="legend-color" style="background:var(--lavender)"></i>${t('2–3 erreurs','2–3 mistakes')}</span><span><i class="legend-color" style="background:var(--coral)"></i>${t('4+ erreurs','4+ mistakes')}</span></div><details class="accordion"><summary>${t('Voir les valeurs par touche','View per-key values')}</summary><div class="score-table-wrap"><table class="score-table"><caption>${t('Touches de l’exercice · données d’exemple','Exercise keys · example data')}</caption><thead><tr><th>${t('Touche','Key')}</th><th>${t('Erreurs','Mistakes')}</th><th>${t('Frappes','Keystrokes')}</th><th>${t('Taux','Rate')}</th></tr></thead><tbody>${heatData.map(([key,errors,total])=>`<tr><td>${key}</td><td>${errors}</td><td>${total}</td><td>${total?Math.round(errors/total*100)+' %':t('Aucune donnée','No data')}</td></tr>`).join('')}</tbody></table></div></details><p class="small" style="margin-top:12px">${t('Clavier illustratif, pas une détection de ta disposition. La table donne les chiffres sans dépendre de la couleur.','Illustrative keyboard, not a detected layout. The table provides values without relying on color.')}</p>`;}
function rankingTable(total=8) {return `<div class="score-table-wrap"><table class="score-table"><caption>${t('Classement public d’exemple','Example public ranking')}</caption><thead><tr><th>${t('Rang','Rank')}</th><th>${t('Joueur','Player')}</th><th>${t('MPM','WPM')}</th><th>${t('Précision','Accuracy')}</th><th>${t('État','Status')}</th></tr></thead><tbody>${Array.from({length:total},(_,i)=>`<tr class="${i===1?'personal':''}"><td>${i+1}</td><td>${i===1?t('Toi','You'):demoName(names[i%names.length])}${i===5?' · Bot':''}</td><td>${i<3?[71,64,59][i]:Math.max(18,56-(i-3)*3)}</td><td>${i<3?[99,98,97][i]:Math.max(82,96-(i-3))} %</td><td>${i===total-1?t('Abandon','Left'):t('Terminé','Finished')}</td></tr>`).join('')}</tbody></table></div>`;}
function resultsPage() {const archived=state.scenario==='history';const host=!archived&&(state.host||state.scenario==='host');const arcade=state.room.mode==='arcade'||state.scenario==='arcade';return heading(t('Une course, des repères','One race, useful insights'),t('Chaque touche compte.','Every key counts.'),t('Un classement pour le groupe. Des repères pour ta prochaine course. Toutes les données ci-dessous sont des exemples.','A ranking for your group. Insights for your next race. All data below are examples.'),host?action('rematch',t('Revanche','Race again'),'primary')+action('close-room',t('Fermer la salle','Close room')):archived?link('history',t('Retour à l’historique','Back to history'),'primary'):link('lobby',t('Retour au salon','Back to lobby'),'primary'))+(archived?note(t('Une course de ton historique','A race from your history'),t('Détail en lecture seule. La salle peut être fermée; aucune commande de revanche n’est proposée ici.','Read-only detail. The room may be closed; no rematch controls appear here.')):'')+(arcade?note(t('Résultat arcade ≠ performance comparable','Arcade result ≠ comparable performance'),t('Les capacités ont un effet sur le jeu. Les mesures de frappe restent séparées des courses classiques.','Abilities affect the game. Typing measurements stay separate from classic races.'),'colorful'):'')+`<section class="panel"><div class="panel-top result-header"><div><h2>${esc(state.room.name)}</h2><p class="small">${t('Podium d’exemple · règle de classement à valider','Example podium · scoring rule to validate')}</p></div>${chip(arcade?'Arcade':t('Classique','Classic'))}</div><ol class="podium" role="list" aria-label="${t('Podium d’exemple','Example podium')}">${[[demoName('Nova'),'first','var(--sky)','71','99',t('Première place','First place')],[t('Toi','You'),'second','var(--accent)','64','98',t('Deuxième place','Second place')],[demoName('Milo'),'third','var(--coral)','59','97',t('Troisième place','Third place')]].slice(0,state.scenario==='few'?2:3).map(([name,klass,color,mpm,precision,label],i)=>`<li class="podium-person ${klass}"><span class="visually-hidden">${label}.</span><div class="avatar" style="--avatar:${color}" aria-hidden="true">${name[0]}</div><strong>${name}</strong><p>${mpm} ${t('MPM','WPM')} · ${precision} %</p><div class="podium-step" aria-hidden="true">0${i+1}</div></li>`).join('')}</ol></section><div class="equal-grid" style="margin-top:24px"><section class="box"><p class="eyebrow">${t('Ta course, en détail','Your race, in detail')}</p><h2>${t('Le rythme se construit.','Rhythm takes practice.')}</h2>${state.scenario==='empty'?note(t('Pas de comparaison disponible','No comparison available'),t('Il faut une autre course avec les mêmes règles pour afficher une évolution.','Another race with the same rules is needed to show progress.')):`<p class="small">${t('Exemple comparable : 3 erreurs de moins sur deux exercices aux mêmes règles. Ce progrès n’est pas calculé par la maquette.','Comparable example: 3 fewer errors across two exercises with the same rules. The prototype does not calculate this progress.')}</p>`}<div class="metric-top" style="margin:24px 0"><div class="metric"><strong>64</strong><span>${t('MPM','WPM')}</span></div><div class="metric"><strong>98 %</strong><span>${t('Précision','Accuracy')}</span></div><div class="metric"><strong>7</strong><span>${t('Erreurs','Mistakes')}</span></div></div><details class="accordion"><summary>${t('Mon rythme pendant cette course','My rhythm during this race')}</summary><p class="small">${t('Six repères à intervalles de 10 secondes, données d’exemple : 48 · 56 · 61 · 64 · 63 · 64 MPM.','Six samples every 10 seconds, example data: 48 · 56 · 61 · 64 · 63 · 64 WPM.')}</p><div class="chart-bars" role="img" aria-label="${t('Évolution MPM d’exemple : 48, 56, 61, 64, 63, 64','Example WPM timeline: 48, 56, 61, 64, 63, 64')}">${[48,56,61,64,63,64].map((n,i)=>`<div class="chart-col"><b>${n}</b><div class="chart-bar" style="height:${n}px"></div><span>${(i+1)*10} s</span></div>`).join('')}</div></details>${link('practice',t('Pratiquer mes touches','Practice my keys'),'subtle')}<p class="small" style="margin-top:16px">${state.identity==='guest'?t('Résultat conservé dans la session invitée active.','Result kept during the active guest session.'):t('Avec un compte, cette course rejoint l’historique.','With an account, this race is added to history.')}</p></section><section class="box"><p class="eyebrow">${t('Les touches à apprivoiser','Keys to get comfortable with')}</p><h2>${t('Une petite carte de ta frappe.','A small map of your typing.')}</h2>${heatmap()}</section></div><section class="box" style="margin-top:24px"><div class="section-heading"><h2>${t('Le groupe, jusqu’à la dernière touche.','The group, until the last key.')}</h2>${action('scoring',t('Comprendre le classement','Understand scoring'),'ghost')}</div>${rankingTable(state.scenario==='few'?2:8)}${!host&&!archived?`<p class="small" style="margin-top:16px">${t('L’hôte décide de la revanche ou de la fermeture. Tu peux revenir au salon ou quitter.','The host decides on a rematch or closing. You can return to the lobby or leave.')}</p>`:''}</section>`;}
function practicePage() {return heading(t('Un peu de pratique, beaucoup de rythme','A little practice, a lot of rhythm'),t('À ton rythme, avec les bots.','At your pace, with bots.'),t('Choisis ton exercice et tes compagnons de frappe. Ici, aucun bonus : tes mesures restent comparables.','Choose your exercise and typing companions. No bonuses here: your measurements stay comparable.'))+`<div class="content-grid"><form id="practice-form" class="box"><h2>${t('Ce que tu veux pratiquer','What you want to practice')}</h2><div class="field-row">${select('practice-language',t('Langue du texte','Text language'),[['fr','Français','French'],['en','Anglais','English']],state.room.language)}${select('practice-target',t('Focus de l’exercice','Exercise focus'),[['accents','Les accents','Accents'],['punctuation','La ponctuation','Punctuation'],['numbers','Les chiffres','Numbers'],['mixed','Un peu de tout','A bit of everything']],'accents')}</div>${select('practice-duration',t('Durée','Duration'),[['30','30 secondes','30 seconds'],['60','60 secondes','60 seconds'],['none','À mon rythme, sans limite','At my pace, no time limit']],'60')}<h2 style="margin-top:24px">${t('Tes compagnons de frappe','Your typing companions')}</h2><div class="bot-grid">${[['gentle','var(--pink)',t('Bot doux','Gentle bot'),t('Pour prendre confiance','To build confidence'),'25–35'],['steady','var(--lavender)',t('Bot régulier','Steady bot'),t('Pour trouver ton rythme','To find your rhythm'),'45–60'],['quick','var(--sky)',t('Bot rapide','Fast bot'),t('Pour te donner un défi','For a challenge'),'75–90']].map(([value,color,title,desc,range])=>`<div class="bot-card"><div class="avatar" style="--avatar:${color}" aria-hidden="true">${value[0].toUpperCase()}</div><strong>${title}</strong><p>${desc}<br>${range} ${t('MPM indicatifs','suggested WPM')}</p><label><input type="checkbox" name="bot" value="${value}" aria-label="${t('Choisir ','Select ')+title}" ${value==='gentle'&&state.scenario!=='error'?'checked':''}>${t('Choisir','Select')}</label></div>`).join('')}</div><p class="small" style="margin:16px 0">${t('Plages proposées. Les bots réels varieront leur vitesse et leurs erreurs; ils ne sont pas pilotés dans cette maquette.','Proposed ranges. Real bots will vary their speed and mistakes; they do not run in this prototype.')}</p><span class="form-error" id="practice-error" aria-live="polite">${state.scenario==='error'?t('Choisis au moins un bot pour préparer cet exercice.','Select at least one bot to prepare this exercise.'):''}</span><button class="primary" type="submit">${t('Préparer mon entraînement','Prepare practice')} ${icon('arrow')}</button></form><aside class="box tinted" style="--tint:var(--accent)"><p class="eyebrow">${t('Les petites victoires','Small victories')}</p><h2>${t('La précision vient avant la précipitation.','Accuracy comes before rushing.')}</h2><p>${t('Quelques mots, une touche difficile, puis un autre essai. Tu n’as pas besoin de gagner pour progresser.','A few words, one tricky key, then another try. You do not need to win to improve.')}</p><p class="small">${t('La maquette propose un exercice local aux invités, sans créer de salle. Ce parcours reste une hypothèse à valider; la création d’une vraie salle exige un compte.','The prototype offers guests a local exercise without creating a room. This path needs validation; creating a real room requires an account.')}</p></aside></div>`;}
function profileTabs() {return `<nav class="detail-tabs" aria-label="${t('Statistiques personnelles','Personal statistics')}">${link('profile',t('Vue d’ensemble','Overview'),'')}${link('history',t('Historique','History'),'')}${link('global-map',t('Mes touches','My keys'),'')}</nav>`;}
function profilePage() {const guest=state.identity==='guest'||state.scenario==='guest';if(state.scenario==='empty')return heading(t('Ton espace de progression','Your progress space'),t('Ta première course t’attend.','Your first race awaits.'),t('Une course suffit pour commencer ton histoire. Aucun chiffre inventé quand l’historique est vide.','One race starts your story. No invented numbers when your history is empty.'))+profileTabs()+empty('0',t('Une page prête à se remplir.','A page ready to fill.'),t('Rejoins ton groupe ou commence par un entraînement.','Join your group or start with practice.'),link('rooms',t('Trouver une course','Find a race'),'primary')+link('practice',t('M’entraîner','Practice')));return `<div class="profile-banner"><div class="avatar" aria-hidden="true">${esc(state.pseudo[0])}</div><div><p class="eyebrow" style="color:#171c2b">${guest?t('Session invitée','Guest session'):t('Ton espace de progression','Your progress space')}</p><h1 id="page-title">${t('Salut','Hi')}, ${esc(state.pseudo)}.</h1><p class="small">${t('Ton rythme se construit, course après course.','Your rhythm builds, race after race.')}</p></div><div class="actions">${link('practice',t('M’entraîner','Practice'),'primary')}${link('preferences',t('Préférences','Preferences'),'subtle')}</div></div>${guest?note(t('Le progrès de cette session','Progress from this session'),t('Ces résultats d’exemple représentent ta session active. Ils ne promettent pas un historique demain.','These example results represent your active session. They do not promise a history tomorrow.')):note(t('Données de démonstration','Demonstration data'),t('Exemple d’un profil connecté. Aucun historique réel n’est enregistré dans la maquette.','Example of a signed-in profile. No real history is saved in the prototype.'))}${profileTabs()}${metrics([[guest?'61':'54',t('MPM moyens · exemple','Average WPM · example')],['96 %',t('Précision moyenne','Average accuracy')],[guest?'3':'24',t('Courses','Races')],[guest?'0':'6',t('Victoires · exemple','Wins · example')],[guest?'3 / 8':'4 / 8',t('Classement moyen · exemple','Average rank · example')]])}<div class="equal-grid"><section class="box">${guest?`<p class="eyebrow">${t('Pendant cette session','During this session')}</p><h2>${t('Trois départs. Trois repères.','Three races. Three insights.')}</h2><p class="small">${t('Les trois exemples utilisent des règles ou langues différentes. Une autre course comparable sera nécessaire pour tracer une évolution.','These three examples use different rules or languages. Another comparable race is needed to chart progress.')}</p><div class="actions" style="margin-top:24px">${link('history',t('Voir ma session','View my session'),'subtle')}</div>`:`<p class="eyebrow">${t('Même règle, même repère','Same rules, same measure')}</p><h2>${t('Un rythme qui se dessine.','A rhythm taking shape.')}</h2><p class="small">${t('Cinq courses classiques françaises comparables · valeurs d’exemple.','Five comparable French classic races · example values.')}</p><div class="chart-bars" role="img" aria-label="${t('MPM d’exemple : 42, 46, 49, 53, 54.','Example WPM: 42, 46, 49, 53, 54.')}">${[42,46,49,53,54].map((n,i)=>`<div class="chart-col"><b>${n}</b><div class="chart-bar" style="height:${n*2}px"></div><span>${t('Course','Race')} ${i+1}</span></div>`).join('')}</div><p class="small" style="margin-top:18px">${t('Valeurs : 42 · 46 · 49 · 53 · 54 MPM. Les courses arcade sont séparées.','Values: 42 · 46 · 49 · 53 · 54 WPM. Arcade races are separate.')}</p>`}</section><section class="box progress-card"><p class="eyebrow" style="color:#171c2b">${t('Progression proposée','Proposed progression')}</p><h2>${t('Chaque course ajoute une touche.','Every race adds a key.')}</h2><p>${t('Palier 3 · Rythme régulier','Level 3 · Steady rhythm')}</p><div class="progress-track" role="progressbar" aria-label="${t('Progression d’exemple vers le palier suivant','Example progress to next level')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="64"><span></span></div><p class="small">${t('64 / 100 points d’exemple. Les récompenses et leur calcul restent à valider.','64 / 100 example points. Rewards and calculation still need validation.')}</p>${link('practice',t('Travailler la touche é','Practice the é key'),'subtle')}</section></div><section class="box" style="margin-top:24px"><div class="section-heading"><h2>${t('Ton dernier exercice, touche par touche.','Your last exercise, key by key.')}</h2>${chip(t('Heatmap de course','Race heatmap'))}</div><p class="small">${t('La heatmap globale est une extension souhaitable. Cette carte illustre une course.','The global heatmap is a desirable extension. This map illustrates one race.')}</p>${heatmap()}</section>`;}
const historyRows = [['02/10','Le sprint des mots','Classique','Français',64,98,'2 / 8'],['02/10','La touche surprise','Arcade','Français',58,95,'4 / 8'],['01/10','Word sprint','Classique','Anglais',49,96,'3 / 12'],['01/10','Les accents','Entraînement','Français',54,97,'—'],['30/09','Une petite aventure','Classique','Français',53,96,'2 / 6']];
