 const p=pageMeta();document.getElementById('screen-picker').innerHTML=pages.map(x=>`<option value="${x[0]}" ${x[0]===state.page?'selected':''}>${t(x[2],x[3])}</option>`).join('');document.getElementById('scenario-picker').innerHTML=p[4].map(key=>`<option value="${key}" ${key===state.scenario?'selected':''}>${t(...scenarioNames[key])}</option>`).join('');
