let liveInput, liveSpans=[], liveSample=[], composing=false, feedbackTimer, toastTimer, dialogOpener;
function render(focus=false,newScenario=false) {const same=app.dataset.page===state.page;if(same&&state.page==='race'&&liveInput?.isConnected)state.typing=liveInput.value;const active=document.activeElement;const focusKey=same?(active.id?'#'+CSS.escape(active.id):active.dataset.action?'[data-action="'+active.dataset.action+'"]':null):null;const draft=same&&!newScenario?[...app.querySelectorAll('input[id],select[id],textarea[id],input[name]')].filter(el=>el.id!=='live-input'&&el.type!=='password').map(el=>({key:el.id?'#'+CSS.escape(el.id):'input[name="'+CSS.escape(el.name)+'"][value="'+CSS.escape(el.value)+'"]',value:el.value,checked:el.checked})):[];clearTimeout(feedbackTimer);chrome();app.innerHTML=renderers[state.page]();app.dataset.page=state.page;app.dataset.scenario=state.scenario;if(same)draft.forEach(d=>{const el=app.querySelector(d.key);if(el){el.value=d.value;if(['checkbox','radio'].includes(el.type))el.checked=d.checked;}});if(same&&!newScenario)app.querySelectorAll('#filter-lang,#history-mode,#content-type,#room-name,#content-language,#race-mode,input[name=access]:checked').forEach(el=>el.dispatchEvent(new Event('change',{bubbles:true})));if(state.page==='race')setupTyping();if(state.scenario==='reconnect')app.querySelectorAll('[data-action]').forEach(b=>{if(!['leave','focus','ranking'].includes(b.dataset.action))b.disabled=true;});document.querySelectorAll('.detail-tabs a').forEach(a=>{if(a.hash==='#'+pageMeta()[1])a.setAttribute('aria-current','page');});if(!focus&&focusKey)document.querySelector(focusKey)?.focus({preventScroll:true});if(focus){app.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function go(page,scenario='normal') {if(dialog.open)dialog.close();state.scenario=scenario;if(state.page===page) {render(true);return;} location.hash=pages.find(p=>p[0]===page)[1];}
function readRoute() {if(location.hash==='#page-content'){app.focus();return;}const found=pages.find(p=>p[1]===location.hash.slice(1));state.page=found?found[0]:location.hash?'unavailable':'home';if(!pageMeta()[4].includes(state.scenario))state.scenario='normal';if(state.page!=='race')state.focus=false;render(true);}
window.addEventListener('hashchange',readRoute);
document.getElementById('screen-picker').addEventListener('change',event=>go(event.target.value));
document.getElementById('scenario-picker').addEventListener('change',event=>{state.scenario=event.target.value;render(false,true);});
function toast(message) {clearTimeout(toastTimer);let el=document.getElementById('site-toast');el.textContent=message;el.hidden=false;toastTimer=setTimeout(()=>{el.hidden=true;},5000);}
function openDialog(title,content,wide=false) {dialogOpener=document.activeElement;dialog.classList.toggle('wide',wide);document.getElementById('dialog-content').innerHTML=`${action('close-dialog',icon('close'),'subtle dialog-close',`autofocus aria-label="${t('Fermer','Close')}"`)}<h2 id="dialog-title">${title}</h2>${content}`;dialog.showModal();document.getElementById('site-toast').hidden=true;}
dialog.addEventListener('close',()=>{if(dialogOpener&&dialogOpener.isConnected)dialogOpener.focus();});
function mapDialog() {openDialog(t('Tout le site, d’une touche à l’autre.','The whole site, from key to key.'),`<p class="small">${t('20 pages de conception, avec leurs variantes. Le menu bleu permet aussi d’explorer les états vides, erreurs et permissions.','20 design pages, with their variants. The blue menu also explores empty states, errors and permissions.')}</p><div class="dialog-card-grid">${pages.map((p,i)=>`<a class="dialog-page" href="#${p[1]}" data-map-page="${p[0]}"><small>${String(i+1).padStart(2,'0')}</small><strong>${t(p[2],p[3])}</strong><small>${p[4].length} ${t('état(s)','state(s)')}</small></a>`).join('')}</div>`,true);}
