 'edit-config':()=>{if(state.identity!=='account'){toast(t('La création exige toujours un compte.','Creation still requires an account.'));return;}go('create');},
 'invite-code':()=>openDialog(t('Place au groupe.','Make room for the group.'),`<p class="small">${t('Un code pour rejoindre cette salle semi-publique.','One code to join this unlisted room.')}</p><div class="box quiet" style="margin:20px 0;display:flex;justify-content:space-between;align-items:center"><b class="code">K7M2PX</b>${action('copy-code',icon('copy'),'subtle',`aria-label="${t('Copier le code','Copy code')}"`)}</div><p class="small">${t('Code d’exemple. Le QR reste une option à intégrer pour les salles semi-publiques.','Example code. QR remains an optional addition for unlisted rooms.')}</p><p id="dialog-feedback" class="small" role="status" style="min-height:25px;margin-top:14px"></p>${action('close-dialog',t('Revenir au salon','Back to lobby'),'primary full')}`),
