 ability:()=>openDialog(t('Rattraper sans effacer l’effort.','Catch up without erasing effort.'),`<p class="small">${t('Deux propositions à équilibrer et tester. Frappe correcte pour charger l’énergie; attribution surtout aux personnes en retard.','Two proposals to balance and test. Correct typing charges energy; availability favors players behind.')}</p><div class="box tinted" style="margin-top:20px"><h3>${t('Tempo · élan personnel','Tempo · personal momentum')}</h3><p>${t('Un soutien temporaire à la progression de jeu, sans changer le texte ni les mesures brutes.','Temporary game progress support, without changing text or raw metrics.')}</p></div><div class="box tinted" style="--tint:var(--pink);margin-top:14px"><h3>${t('Relais · seconde chance','Relay · second chance')}</h3><p>${t('Atténue ponctuellement une pénalité de jeu quand tu es en retard. Les erreurs réelles restent enregistrées.','Temporarily softens a game penalty when behind. Real mistakes stay recorded.')}</p></div><p class="small" style="margin-top:16px">${t('Pas d’obstruction du texte. Aucun effet exécuté ici. Ni formule ni seuil déjà approuvés.','No text obstruction. No effect runs here. Formula and thresholds are not approved yet.')}</p>`),
 'history-detail':button=>{state.room.name=button.dataset.name;state.room.mode=button.dataset.mode;state.room.language=button.dataset.language;state.host=false;go('results','history');},'example-results':()=>go('results',state.scenario==='arcade'?'arcade':'normal'),scoring:()=>openDialog(t('Le même repère pour le groupe.','The same measure for the group.'),`<p>${t('La formule commune combinera vitesse et précision. La pénalité d’erreurs non bloquantes reste à décider et à tester.','The shared formula will combine speed and accuracy. Non-blocking error penalties still need a decision and testing.')}</p><p class="small">${t('Le podium affiché est un exemple visuel, pas un résultat calculé par la maquette. Arcade et classique ne sont pas comparés directement.','The displayed podium is a visual example, not a result calculated by the prototype. Arcade and classic are not directly compared.')}</p>`),
 rematch:()=>{state.host=true;state.ready=false;state.typing='';go('lobby');},'close-room':()=>openDialog(t('Fermer la salle ?','Close the room?'),`<p class="small">${t('Le groupe ne pourra plus rejoindre cette salle. Les résultats déjà validés restent dans leurs historiques.','The group cannot join this room anymore. Already validated results stay in their histories.')}</p><div class="actions" style="margin-top:24px">${action('close-dialog',t('Garder ouverte','Keep open'),'primary')}${action('confirm-close',t('Fermer l’exemple','Close example'))}</div>`),'confirm-close':()=>{dialog.close();go('unavailable','closed');},
 leave:()=>openDialog((state.host||['host','transfer'].includes(state.scenario))?t('Passer le relais avant de partir.','Pass the baton before leaving.'):t('Quitter cette course ?','Leave this race?'),(state.host||['host','transfer'].includes(state.scenario))?`<p class="small">${t('Une courte déconnexion garde ta place. Un départ volontaire transmet le rôle au participant choisi, sinon au plus ancien éligible.','A short disconnection keeps your place. Leaving voluntarily passes the host role to a chosen participant, otherwise the oldest eligible one.')}</p>${select('successor',t('Prochain hôte','Next host'),[['oldest','Le plus ancien éligible','Oldest eligible'],['Milo','Milo','Milo'],['Lune','Lune','Lune']],'oldest')}<div class="actions">${action('close-dialog',t('Rester','Stay'),'primary')}${action('confirm-leave',t('Transférer et quitter l’exemple','Transfer and leave example'))}</div>`:`<p class="small">${t('Ton abandon ne bloquera pas la fin du groupe. Une reconnexion temporaire est traitée différemment d’un départ volontaire.','Leaving will not block the group from finishing. Temporary reconnection is different from leaving voluntarily.')}</p><div class="actions" style="margin-top:22px">${action('close-dialog',t('Rester','Stay'),'primary')}${action('confirm-leave',t('Quitter l’exemple','Leave example'))}</div>`),
 'confirm-leave':()=>{dialog.close();state.host=false;state.practice=false;go('home');},'close-dialog':()=>dialog.close(),signout:()=>{state.identity='anonymous';state.host=false;go('home');toast(t('Identité d’exemple déconnectée.','Example identity signed out.'));}
