document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button){if(dialog.open&&!dialog.contains(button))return;actions[button.dataset.action]?.(button);}const a=event.target.closest('a[href^="#"]');if(a){if(a.hash==='#page-content'){event.preventDefault();app.focus();return;}if(dialog.open)dialog.close();if(a.hasAttribute('data-map-page')){event.preventDefault();go(a.dataset.mapPage);}else state.scenario='normal';}});
function formError(id,message,fieldId) {document.getElementById(id).textContent=message;if(fieldId){let f=document.getElementById(fieldId);f.setAttribute('aria-invalid','true');f.setAttribute('aria-describedby',[f.getAttribute('aria-describedby')||'',id].join(' ').trim());f.focus();}}
document.addEventListener('submit',event=>{event.preventDefault();let f=event.target;let value=id=>document.getElementById(id).value.trim();
 if(f.id==='join-form'){if(value('room-code').toUpperCase()!=='K7M2PX'){formError('code-error',t('Ce code ne correspond à aucune salle active. Essaie K7M2PX.','This code does not match an active room. Try K7M2PX.'),'room-code');return;}state.room.access='semi';state.host=false;state.practice=false;enter();}
 if(f.id==='login-form'){if(!value('login-name')||!value('login-password')){formError('login-error',t('Renseigne les deux champs avec des valeurs d’exemple.','Fill both fields with example values.'),!value('login-name')?'login-name':'login-password');return;}authDone(value('login-name'));}
 if(f.id==='register-form'){if(!value('register-name')||!value('register-password')){formError('register-error',t('Renseigne le nom et un mot de passe d’exemple.','Enter a name and an example password.'),!value('register-name')?'register-name':'register-password');return;}if(value('register-password')!==value('register-confirm')){formError('register-error',t('Les mots de passe ne correspondent pas.','Passwords do not match.'),'register-confirm');return;}authDone(value('register-name'));}
 if(f.id==='guest-form'){if(!value('guest-name')){formError('guest-error',t('Choisis un pseudonyme pour entrer.','Choose a nickname to join.'),'guest-name');return;}state.identity='guest';state.pseudo=value('guest-name');let pending=state.pending;state.pending='lobby';go(pending==='create'?'home':pending);}
 if(f.id==='create-form'){let custom=value('custom-text'),excluded=[...value('excluded-characters').replace(/\s/g,'')];if(!value('room-name')){formError('create-error',t('Donne un nom à ta salle.','Give your room a name.'),'room-name');return;}if(value('content-type')==='custom'&&!custom){formError('create-error',t('Ajoute ton texte personnalisé.','Add your custom text.'),'custom-text');return;}if(value('content-type')==='custom'&&excluded.some(c=>custom.includes(c))){formError('create-error',t('Le texte contient un caractère exclu. Corrige le texte ou les exclusions.','The text contains an excluded character. Correct the text or exclusions.'),'custom-text');return;}if(value('speed-target')&&(Number(value('speed-target'))<1||Number(value('speed-target'))>250)){formError('create-error',t('L’objectif proposé doit être entre 1 et 250 MPM.','The proposed goal must be between 1 and 250 WPM.'),'speed-target');return;}state.room={name:value('room-name'),access:f.querySelector('input[name=access]:checked').value,language:value('content-language'),content:value('content-type'),duration:value('race-duration'),length:value('text-length'),mode:value('race-mode'),errors:value('race-errors'),custom,topic:value('text-theme'),targets:[...f.querySelectorAll('input[name=target]:checked')].map(el=>el.value),excluded:value('excluded-characters'),bots:value('room-bots'),speedGoal:value('speed-target')};if(state.room.content!=='custom'&&excluded.some(c=>exerciseText().includes(c))){formError('create-error',t('Le texte d’exemple contient un caractère exclu. Choisis un texte personnalisé compatible ou ajuste les exclusions.','The sample text contains an excluded character. Choose compatible custom text or adjust exclusions.'),'excluded-characters');return;}state.host=true;state.ready=false;state.practice=false;go('lobby');toast(t('Salon d’exemple configuré. Aucune salle réseau créée.','Example lobby configured. No network room created.'));}
 if(f.id==='practice-form'){state.typing='';if(!f.querySelector('input[name=bot]:checked')){formError('practice-error',t('Choisis au moins un bot pour ce parcours d’exemple.','Choose at least one bot for this example path.'));return;}state.practice=true;state.host=false;state.room.language=value('practice-language');state.room.duration=value('practice-duration');state.room.mode='classic';state.room.content='text';state.room.custom='';state.room.errors='free';state.room.name=t('Les petites victoires','Small victories');go('countdown');}
 if(f.id==='preferences-form'){state.locale=value('pref-language');state.theme=value('pref-theme');state.sound=document.getElementById('pref-sound').checked;state.motion=!document.getElementById('pref-motion').checked;state.effects=!document.getElementById('pref-effects').checked;state.brand=value('brand-choice');document.documentElement.classList.toggle('wireframe',document.getElementById('grayscale').checked);render();toast(t('Préférences appliquées à cette maquette.','Preferences applied to this prototype.'));}
});
document.addEventListener('change',event=>{let el=event.target;if(el.name==='access'){document.getElementById('access-explanation').innerHTML=icon('link')+'<span>'+accessText(el.value)+'</span>';}if(el.id==='content-type')document.getElementById('custom-field').hidden=el.value!=='custom';if(['room-name','content-language','content-type','custom-text','race-mode','race-duration','race-errors'].includes(el.id)){const title=document.getElementById('config-preview-title');if(title)title.textContent=document.getElementById('room-name').value;const preview=document.getElementById('config-preview-text');const meta=document.getElementById('config-preview-meta');if(meta)meta.innerHTML=chip(document.getElementById('content-language').value==='fr'?t('Français','French'):t('Anglais','English'))+chip(document.getElementById('race-mode').value==='arcade'?'Arcade':t('Classique','Classic'));if(preview)preview.textContent=document.getElementById('content-type').value==='custom'?document.getElementById('custom-text').value:document.getElementById('content-language').value==='fr'?'Chaque touche te rapproche du prochain défi.':'Every key brings you closer to the next challenge.';}
 if(el.id.startsWith('filter-')){let lang=document.getElementById('filter-lang').value,mode=document.getElementById('filter-mode').value,status=document.getElementById('filter-state').value;let rooms=publicRooms.filter(r=>(lang==='all'||r.lang===lang)&&(mode==='all'||r.mode===mode)&&(status==='all'||(status==='racing')===r.active));let target=document.getElementById('public-rooms');if(target)target.innerHTML=rooms.length?roomCards(rooms):`<p class="small" role="status">${t('Aucune course pour ces filtres.','No races match these filters.')}</p>`;}
 if(el.id.startsWith('history-')){let mode=document.getElementById('history-mode').value,lang=document.getElementById('history-language').value;let guest=state.identity==='guest'||state.scenario==='guest';let rows=(guest?historyRows.slice(0,3).map(r=>['02/10',...r.slice(1)]):historyRows).filter(r=>(mode==='all'||r[2]==={classic:'Classique',arcade:'Arcade',practice:'Entraînement'}[mode])&&(lang==='all'||r[3]==={fr:'Français',en:'Anglais'}[lang]));document.getElementById('history-rows').innerHTML=historyBody(rows);}
});
function setupTyping() {const key=exerciseText();if(state.typingKey!==key){state.typing='';state.typingKey=key;}liveInput=document.getElementById('live-input');if(!liveInput)return;liveSpans=[];liveSample=[...exerciseText().normalize('NFC')];let out=document.getElementById('live-text');for(let word of exerciseText().match(/\S+\s*|\s+/g)||[]){let group=document.createElement('span');group.className='typing-word';for(let char of word.normalize('NFC')){let span=document.createElement('span');span.textContent=char;group.append(span);liveSpans.push(span);}out.append(group);}composing=false;liveInput.addEventListener('compositionstart',()=>{composing=true;});liveInput.addEventListener('compositionend',()=>{composing=false;updateTyping(liveInput.value);});liveInput.addEventListener('input',()=>{if(!composing)updateTyping(liveInput.value);});liveInput.addEventListener('paste',event=>{event.preventDefault();clearTimeout(feedbackTimer);document.getElementById('live-feedback').textContent=t('Le collage est désactivé pour cet exercice.','Paste is disabled for this exercise.');});liveInput.value=state.typing;updateTyping(state.typing,true);}
function updateTyping(value,initial=false) {state.typing=value;const chars=[...value.normalize('NFC')];let correct=0,errors=0,firstError=-1;liveSpans.forEach((span,i)=>{let klass='';if(i<chars.length){let right=chars[i]===liveSample[i];if(right)correct++;else{errors++;if(firstError===-1)firstError=i;}klass=right?'correct':'error';}if(i===chars.length)klass+=' cursor';if(chars.length>=liveSample.length&&i===liveSample.length-1)klass+=' end-cursor';span.className=klass.trim();});errors+=Math.max(0,chars.length-liveSample.length);let blocking=state.scenario==='blocking'||state.room.errors==='block';let progress=Math.min(100,Math.round((blocking&&firstError!==-1?firstError:chars.length)/liveSample.length*100));document.getElementById('live-accuracy').textContent=chars.length?Math.round(correct/chars.length*100)+' %':'—';let bar=document.getElementById('live-progress');bar.style.setProperty('--progress',progress+'%');bar.setAttribute('aria-valuenow',String(progress));document.getElementById('live-percent').textContent=progress+' %';if(initial)return;clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>{document.getElementById('live-feedback').textContent=blocking&&firstError!==-1?t(`Corrige la touche ${liveSample[firstError]} avant de poursuivre.`,`Correct the ${liveSample[firstError]} key before continuing.`):`${progress} % · ${errors} ${t('erreur(s)','mistake(s)')}`;},600);}
readRoute();
